package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class LongWrittenDivisionTest {
 private Question make(int n,int d){return ShortWrittenDivision.indexedLong((n-1)*90+d-10);}
 private int[] repeated(int n,int d){int quotient=0;while(n>=d){n-=d;quotient++;}return new int[]{quotient,n};}
 @Test public void everyDivisorAndSelectedDividendBoundariesUsePublicDivisionAndFormalRows(){Checker c=new Checker();for(int d=10;d<=99;d++)for(int n:new int[]{1,9,10,d-1,d,d+1,99,100,101,999,1000,1001,4001,9090,9999}){Question q=make(n,d);int[] expected=repeated(n,d);q.answers=new String[]{"poison","poison"};q.expression="poison";assertTrue(c.check(q,List.of(),List.of(""+expected[0],""+expected[1])).correct());assertEquals(1,c.check(q,List.of(),List.of(""+expected[0],""+(expected[1]+1))).index);VerticalWork.Layout l=VerticalWork.layout(q);assertNotNull(l);assertEquals(Integer.toString(n).length(),l.rows.stream().filter(r->r.id.startsWith("product")).count());HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertEquals(2+4*Integer.toString(n).length(),h.size());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));int rest=0,step=2;for(char ch:Integer.toString(n).toCharArray()){int current=rest*10+ch-'0';int[] local=repeated(current,d);assertTrue(h.step(step++).accepts(""+current));assertTrue(h.step(step++).accepts(""+local[0]));assertTrue(h.step(step++).accepts(""+(current-local[1])));rest=local[1];assertTrue(h.step(step++).accepts(""+rest));}}
  Question q=make(4013,40);VerticalWork.Draft draft=new VerticalWork.Draft();draft.cells.put("product1:1","9");assertEquals(Set.of("product1:1"),VerticalWork.check(q,draft).wrong);assertNull(VerticalWork.answers(q,draft));draft.cells.clear();for(int i=0;i<4;i++)draft.cells.put("answer:"+i,""+(100/(int)Math.pow(10,i)%10));draft.cells.put("rest0:0","3");draft.cells.put("rest0:1","1");assertEquals(List.of("0100","13"),VerticalWork.answers(q,draft));assertFalse(VerticalWork.check(q,draft).error());
 }
 @Test public void twoDigitContextsDistinguishFloorRemainderCeilingAndExactShare(){Checker c=new Checker();for(int d=10;d<=99;d++)for(int n:new int[]{1,d-1,d,d+1,1001,9999})for(Catalog.Skill s:RemainderContexts.SKILLS){Question q=RemainderContexts.indexedTwoDigit(s.id,(n-1)*90+d-10);q.answers=new String[]{"poison"};int[] div=repeated(n,d);String expected=s.id.equals(RemainderContexts.GROUPS)?""+div[0]:s.id.equals(RemainderContexts.LEFT)?""+div[1]:s.id.equals(RemainderContexts.VEHICLES)?""+(div[0]+(div[1]>0?1:0)):n+"/"+d;assertTrue(c.check(q,List.of(),List.of(expected)).correct());HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));assertTrue(h.step(2).accepts(""+div[0]));assertTrue(h.step(3).accepts(""+div[1]));}
 }
 @Test public void yearSixFreshSupplyAndYearFiveBoundsRemainSeparate(){Generator g=new Generator(new Random(193));Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"GB");GlobalCurriculum.choosePack(p,"england-primary-2021-v1");assertTrue(GlobalCurriculum.pack(p).inGrade(ShortWrittenDivision.LONG,6));assertFalse(GlobalCurriculum.pack(p).inGrade(ShortWrittenDivision.LONG,5));assertFalse(Curriculum.inCurriculum(Catalog.get(ShortWrittenDivision.LONG),2022));List<String> ids=new ArrayList<>();ids.add(ShortWrittenDivision.LONG);for(Catalog.Skill s:RemainderContexts.SKILLS)ids.add(s.id);for(String id:ids){List<String> recent=new ArrayList<>();CurriculumLimits limits=GlobalCurriculum.limits(p.educationSystem,id,6);for(int i=0;i<150;i++){Question q=g.next(id,recent,false,limits);int[] v=id.equals(ShortWrittenDivision.LONG)?ShortWrittenDivision.read(q):RemainderContexts.read(q);assertNotNull(v);assertTrue(v[1]>=10&&v[1]<=99);assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertTrue(limits.allows(q));}if(RemainderContexts.supports(id))for(int i=0;i<50;i++){Question q=g.next(id,List.of(),false,GlobalCurriculum.limits(p.educationSystem,id,5));assertTrue(RemainderContexts.read(q)[1]<=9);}}
  for(String prompt:List.of("10000 ÷ 10","0 ÷ 10","12 ÷ 9","12 ÷ 100")){Question q=make(12,10);q.prompt=prompt;assertNull(ShortWrittenDivision.read(q));assertNull(VerticalWork.layout(q));}
 }
}
